package io.github.jackotom.hongguo.android;
import java.io.*;import java.lang.reflect.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Production App transport, legacy-signature DNS stub, no TCP/TLS traffic. */
public final class AppTransportDeadlineTest {
 static int checks,passed,failed; interface Work {void run()throws Exception;}
 static void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}
 static void group(String name,Work work){try{work.run();passed++;System.out.println("PASS "+name);}catch(Throwable error){failed++;System.out.println("FAIL "+name+": "+error);}finally{Thread.interrupted();}}
 static long after(long ms){return System.nanoTime()+ms*1_000_000L;}
 static void request(boolean search,long deadline)throws Exception {Method m=AppTransport.class.getDeclaredMethod("execute",String.class,String.class,Map.class,byte[].class,boolean.class,boolean.class,long.class);m.setAccessible(true);try{m.invoke(null,search?"https://api5-normal-sinfonlineb.fqnovel.com/reading/bookapi/search/tab/v":"https://api5-normal-sinfonlineb.fqnovel.com/novel/player/multi_video_model/v1/","GET",Map.of(),new byte[0],false,search,deadline);}catch(InvocationTargetException e){if(e.getCause()instanceof Exception)throw(Exception)e.getCause();throw(Error)e.getCause();}}
 static long budget(JSONObject params)throws Exception {try{Method method=AppTransport.class.getDeclaredMethod("sourceDeadline",JSONObject.class);method.setAccessible(true);return(Long)method.invoke(null,params);}catch(NoSuchMethodException missing){throw new AssertionError("missing production caller-budget guard");}}
 static Exception rejects(Work work)throws Exception{try{work.run();throw new AssertionError("expected rejection before socket");}catch(IOException error){return error;}}
 static void unblock()throws Exception{NetworkGuard.release.countDown();Thread.sleep(80);NetworkGuard.release=new CountDownLatch(1);}
 public static void main(String[]args)throws Exception {
  group("normal App source DNS has shared deadline and bounded saturation",()->{long start=System.nanoTime();try{check(rejects(()->request(false,after(45)))instanceof SocketTimeoutException,"first App lookup deadline");check(rejects(()->request(false,after(45)))instanceof SocketTimeoutException,"second App lookup deadline");Exception error=rejects(()->request(false,after(500)));check(!(error instanceof SocketTimeoutException),"exhausted pool fails fast without DNS queue");check(NetworkGuard.lookups.get()==2,"at most two stuck legacy DNS workers");check((System.nanoTime()-start)/1_000_000L<700,"bounded request waits");}finally{unblock();}});
  group("expired or pre-cancelled App source never begins DNS",()->{int before=NetworkGuard.lookups.get();check(rejects(()->request(false,System.nanoTime()-1))instanceof SocketTimeoutException,"expired source timeout");Thread.currentThread().interrupt();try{check(rejects(()->request(false,after(500)))instanceof InterruptedIOException,"cancelled source rejection");check(Thread.currentThread().isInterrupted(),"cancelled source retains flag");}finally{Thread.interrupted();}check(NetworkGuard.lookups.get()==before,"expired and cancelled do not submit");});
  group("App source cancellation interrupts DNS wait",()->{int before=NetworkGuard.lookups.get();boolean[] cancelled={false};Thread caller=new Thread(()->{try{request(false,after(5000));}catch(Exception e){cancelled[0]=e instanceof InterruptedIOException&&Thread.currentThread().isInterrupted();}});caller.start();long until=after(500);while(NetworkGuard.lookups.get()==before&&System.nanoTime()<until)Thread.sleep(1);check(NetworkGuard.lookups.get()==before+1,"DNS worker entered");caller.interrupt();caller.join(500);check(!caller.isAlive()&&cancelled[0],"source cancellation returned promptly");unblock();});
  group("search retains shared DNS deadline and no signed POST retry",()->{int before=NetworkGuard.lookups.get();try{check(rejects(()->request(true,after(45)))instanceof SocketTimeoutException,"search timeout remains typed");check(NetworkGuard.lookups.get()==before+1,"one underlying lookup, no request replay");}finally{unblock();}});
  group("JS caller deadlines expire without DNS and reject invalid budget fields",()->{int before=NetworkGuard.lookups.get();String url="https://api5-normal-sinfonlineb.fqnovel.com/novel/player/multi_video_model/v1/";JSONObject result=AppTransport.request(new JSONObject().put("url",url).put("timeoutMs",1000).put("deadlineMs",System.currentTimeMillis()-1));check("ETIMEDOUT".equals(result.optString("errorCode")),"expired caller deadline is typed");for(String field:new String[]{"timeoutMs","deadlineMs"})for(Object invalid:new Object[]{"50",JSONObject.NULL,0,-1,0.5,Boolean.TRUE}){boolean rejected=false;try{AppTransport.request(new JSONObject().put("url",url).put(field,invalid));}catch(IOException expected){rejected=true;}check(rejected,"invalid "+field+" rejected");}check(NetworkGuard.lookups.get()==before,"no expired or invalid budget submits DNS");});
  group("JS budget can only shorten native source timeout",()->{long start=System.nanoTime();long normal=budget(new JSONObject());check(normal-start<=12_050_000_000L,"native default max12s");long clamped=budget(new JSONObject().put("timeoutMs",60000));check(clamped-System.nanoTime()<=12_000_000_000L,"long caller timeout clamped");long shortDeadline=budget(new JSONObject().put("timeoutMs",500).put("deadlineMs",System.currentTimeMillis()+50));check(shortDeadline-System.nanoTime()<=50_000_000L,"wall deadline shortens monotonic budget");});
  System.out.println("APP_TRANSPORT_DEADLINE_"+(failed==0?"OK":"FAILED")+" groupsPassed="+passed+" groupsFailed="+failed+" checks="+checks+" networkRequests=0 socketAttempts=0");if(failed>0)throw new AssertionError("App transport deadline regression gate failed");
 }
}
